export class Position {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    column: number;
    line: number;
}

export class Range {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    end: Position;
    start: Position;
}

export function format(source: string, source_path: string, options: any): Promise<any>;

export function lint(source: string, source_path: string, options: any): Promise<any>;

/**
 * Remove one file from the browser-backed virtual workspace.
 */
export function remove_workspace_file(uri: string): void;

/**
 * Replace the virtual workspace entries visible to `format`/`lint`/`serve`.
 */
export function set_workspace_entries(entries: any): void;

/**
 * Update one file in the browser-backed virtual workspace.
 */
export function set_workspace_file(uri: string, text: string): void;

/**
 * Replace the virtual workspace files visible to `format`/`lint`/`serve`.
 */
export function set_workspace_files(files: any): void;

export function start(): void;

